import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"ক্রনিকলের সংক্ষিপ্ত সারণি","description":"","frontmatter":{},"headers":[],"relativePath":"bn/93-编年史简表.md","filePath":"bn/93-编年史简表.md","lastUpdated":1789183869000}'),h={name:"bn/93-编年史简表.md"};function o(l,t,b,i,n,u){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="ক্রনিকলের-সংক্ষিপ্ত-সারণি" tabindex="-1">ক্রনিকলের সংক্ষিপ্ত সারণি <a class="header-anchor" href="#ক্রনিকলের-সংক্ষিপ্ত-সারণি" aria-label="Permalink to &quot;ক্রনিকলের সংক্ষিপ্ত সারণি&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>93</td></tr><tr><td>মডিউল</td><td>পরিশিষ্ট ও রেফারেন্স উপকরণ</td></tr><tr><td>মূল শব্দগুলি</td><td>ক্রনিকল, যুগ বিভাজন, গুরুত্বপূর্ণ ঘটনা, ঐতিহাসিক নোড, হেঙ্গুয়ানঝো</td></tr></tbody></table><h2 id="১-ক্রনিকলের-বিবরণ" tabindex="-1">১. ক্রনিকলের বিবরণ <a class="header-anchor" href="#১-ক্রনিকলের-বিবরণ" aria-label="Permalink to &quot;১. ক্রনিকলের বিবরণ&quot;">​</a></h2><p>এই সংক্ষিপ্ত সারণিটি হেঙ্গুয়ানঝো মানক সময়কে ভিত্তি করে, যুগ ক্রমানুসারে অ্যাঙ্কর সিম্বায়োসিস সভ্যতার বিকাশের ইতিহাসে গুরুত্বপূর্ণ ঐতিহাসিক ঘটনা এবং মূল নোডগুলি রেকর্ড করে। সময় ব্যাপ্তি প্রাক-অ্যাঙ্কর যুগের প্রাচীন সময় থেকে শুরু করে আন্তঃনাক্ষত্রিক সিম্বায়োসিস যুগের ভবিষ্যতের প্রত্যাশা পর্যন্ত প্রসারিত। প্রতিটি যুগে শুরু ও শেষের সময়, যুগের বৈশিষ্ট্য এবং গুরুত্বপূর্ণ ঘটনাগুলি তালিকাভুক্ত করা হয়েছে। এই সংক্ষিপ্ত সারণিটি অত্যন্ত ঘনীভূত ঐতিহাসিক সূচী; প্রতিটি যুগের বিস্তারিত ইতিহাসের জন্য নথি 70-79-এর বিশেষ লেখা দেখুন।</p><h2 id="২-যুগ-বিভাজনের-সারসংক্ষেপ" tabindex="-1">২. যুগ বিভাজনের সারসংক্ষেপ <a class="header-anchor" href="#২-যুগ-বিভাজনের-সারসংক্ষেপ" aria-label="Permalink to &quot;২. যুগ বিভাজনের সারসংক্ষেপ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>যুগ নম্বর</th><th>যুগের নাম</th><th>শুরু ও শেষের সময় (হেঙ্গুয়ানঝো মানক বছর)</th><th>স্থায়িত্বকাল</th><th>মূল বৈশিষ্ট্য</th></tr></thead><tbody><tr><td>প্রথম যুগ</td><td>প্রাক-অ্যাঙ্কর যুগ</td><td>প্রায় -10000000000 বছর থেকে -10000 বছর</td><td>প্রায় 10000000000 বছর</td><td>লুণ্ঠনশৈলী ক্ষতি প্রধান, সভ্যতার উত্থান-পতন চক্র</td></tr><tr><td>দ্বিতীয় যুগ</td><td>অ্যাঙ্কর জাগরণ যুগ</td><td>-10000 বছর থেকে -1000 বছর</td><td>প্রায় 9000 বছর</td><td>অ্যাঙ্কর প্রক্রিয়া আবিষ্কৃত এবং প্রাথমিকভাবে প্রয়োগ করা হয়</td></tr><tr><td>তৃতীয় যুগ</td><td>সিম্বায়োসিস ব্যবস্থা প্রতিষ্ঠার সময়কাল</td><td>-1000 বছর থেকে -100 বছর</td><td>প্রায় 900 বছর</td><td>অ্যাঙ্কর সিম্বায়োসিস সভ্যতার প্রাতিষ্ঠানিক কাঠামো ধীরে ধীরে প্রতিষ্ঠিত হয়</td></tr><tr><td>চতুর্থ যুগ</td><td>তিনশত সেট ব্যবস্থা খোলার সময়কাল</td><td>-100 বছর থেকে -50 বছর</td><td>প্রায় 50 বছর</td><td>তিনশত সেট মূল ক্ষতি ব্যবস্থা সম্পূর্ণরূপে খোলা হয়</td></tr><tr><td>পঞ্চম যুগ</td><td>20% সক্রিয়করণ কৌশলের সময়কাল</td><td>-50 বছর থেকে মূল বছর</td><td>প্রায় 50 বছর</td><td>20% সত্ত্বা সক্রিয় হয়ে সমতলের সর্বোচ্চ শক্তিশালী হয়</td></tr><tr><td>ষষ্ঠ যুগ</td><td>প্রথম মাত্রা বৃদ্ধি যুগ</td><td>মূল বছর থেকে 100 বছর</td><td>100 বছর</td><td>সিম্বায়োসিস সভ্যতা প্রথমবারের মতো পর্যায়ক্রমিক মাত্রা বৃদ্ধি অর্জন করে</td></tr><tr><td>সপ্তম যুগ</td><td>সব জাতির প্রজাতন্ত্র যুগ</td><td>100 বছর থেকে 500 বছর</td><td>400 বছর</td><td>সব জাতির প্রজাতন্ত্র আনুষ্ঠানিকভাবে প্রতিষ্ঠিত, আন্তঃজাতি সংমিশ্রণ গভীর হয়</td></tr><tr><td>অষ্টম যুগ</td><td>আন্তঃসমতল অনুসন্ধান যুগ</td><td>500 বছর থেকে 2000 বছর</td><td>1500 বছর</td><td>বৃহৎ আকারের আন্তঃসমতল অনুসন্ধান এবং প্রত্নতাত্ত্বিক কার্যক্রম শুরু হয়</td></tr><tr><td>নবম যুগ</td><td>আন্তঃনাক্ষত্রিক সিম্বায়োসিস যুগ</td><td>2000 বছর থেকে ভবিষ্যত</td><td>চলমান</td><td>মহাজাগতিক সিম্বায়োসিস নেটওয়ার্ক নির্মিত, সামগ্রিক মাত্রা বৃদ্ধি এগিয়ে যায়</td></tr></tbody></table><p>নোট: &quot;মূল বছর&quot; বলতে অ্যাঙ্কর সিম্বায়োসিস সভ্যতা আনুষ্ঠানিকভাবে প্রতিষ্ঠার ঘোষণা করা বছরকে বোঝায়, এবং এটি ঐতিহাসিক কালগণনার বিভাজন বিন্দু হিসেবে ব্যবহৃত হয়।</p><h2 id="৩-প্রাক-অ্যাঙ্কর-যুগ-প্রায়-10000000000-বছর-থেকে-10000-বছর" tabindex="-1">৩. প্রাক-অ্যাঙ্কর যুগ (প্রায় -10000000000 বছর থেকে -10000 বছর) <a class="header-anchor" href="#৩-প্রাক-অ্যাঙ্কর-যুগ-প্রায়-10000000000-বছর-থেকে-10000-বছর" aria-label="Permalink to &quot;৩. প্রাক-অ্যাঙ্কর যুগ (প্রায় -10000000000 বছর থেকে -10000 বছর)&quot;">​</a></h2><p>প্রাক-অ্যাঙ্কর যুগ হলো হেঙ্গুয়ানঝোর ইতিহাসে সবচেয়ে দীর্ঘ যুগ, প্রায় একশো কোটি বছর স্থায়ী হয়েছিল। এই যুগের মূল বৈশিষ্ট্য হলো লুণ্ঠনশৈলী ক্ষতি ব্যবস্থা মহাবিশ্বে প্রভাবশালী ছিল, এবং সভ্যতাগুলি &quot;উত্থান—চরম—লুণ্ঠন—পতন&quot; চক্রে বারবার ঘুরতে থাকল।</p><table tabindex="0"><thead><tr><th>সময় নোড</th><th>গুরুত্বপূর্ণ ঘটনা</th></tr></thead><tbody><tr><td>প্রায় -10000000000 বছর</td><td>হেঙ্গুয়ানঝোর নিয়ম নেটওয়ার্ক স্থিতিশীল হয়, প্রথম ব্যাচের পদার্থ সমতল গঠিত হয়, মহাবিশ্ব বাসযোগ্য অবস্থায় প্রবেশ করে</td></tr><tr><td>প্রায় -8000000000 বছর</td><td>প্রথম ব্যাচের বুদ্ধিমান জীবন একাধিক পদার্থ সমতলে জন্ম নেয়, আদিম ক্ষতি ব্যবস্থা অঙ্কুরিত হতে শুরু করে</td></tr><tr><td>প্রায় -5000000000 বছর</td><td>লুণ্ঠনশৈলী ক্ষতি ব্যবস্থা ধীরে ধীরে প্রধান হয়ে ওঠে, শক্তিশালীরা দুর্বলদের গ্রাস করে দ্রুত বিবর্তন অর্জন করে</td></tr><tr><td>প্রায় -3000000000 বছর</td><td>প্রথম মহাজাগতিক লুণ্ঠন যুদ্ধ বিস্ফোরিত হয়, একাধিক নক্ষত্র অঞ্চলের সভ্যতা বিনাশকারী আঘাতের শিকার হয়</td></tr><tr><td>প্রায় -1000000000 বছর</td><td>লুণ্ঠনশৈলী ব্যবস্থার ত্রুটিগুলি প্রকাশ পেতে শুরু করে, মহাবিশ্বের সামগ্রিক এনট্রপি বৃদ্ধি ত্বরান্বিত হয়, ক্ষতি সম্পদ ক্রমশ ক্ষয়প্রাপ্ত হয়</td></tr><tr><td>প্রায় -500000000 বছর</td><td>প্রথম ব্যাচের লুণ্ঠনশৈলী ব্যবস্থা প্রতিফলনকারী চিন্তক আবির্ভূত হয়, সিম্বায়োসিস চিন্তার অঙ্কুর ফুটতে শুরু করে</td></tr><tr><td>প্রায় -100000000 বছর</td><td>একাধিক নক্ষত্র অঞ্চলে ছোট আকারের সিম্বায়োসিস পরীক্ষামূলক সভ্যতা আবির্ভূত হয়, কিন্তু সবগুলো লুণ্ঠনশৈলী সভ্যতা দ্বারা ধ্বংস হয়</td></tr><tr><td>প্রায় -1000000 বছর</td><td>মহাবিশ্ব সামগ্রিকভাবে &quot;মহা পতনের সময়কালে&quot; প্রবেশ করে, সভ্যতার সংখ্যা এবং ক্ষতি স্তর উভয়ই ঐতিহাসিক নিম্নস্তরে নেমে আসে</td></tr><tr><td>প্রায় -10000 বছর</td><td>প্রথম সমতলের একজন ক্ষতিকর দীর্ঘকালীন ক্ষতির মাধ্যমে দুর্ঘটনাক্রমে নিয়ম নেটওয়ার্কের স্থিতিশীল নোডগুলি অনুভব করেন, অ্যাঙ্কর প্রক্রিয়া প্রথমবার আবিষ্কৃত হয়</td></tr></tbody></table><h2 id="৪-অ্যাঙ্কর-জাগরণ-যুগ-10000-বছর-থেকে-1000-বছর" tabindex="-1">৪. অ্যাঙ্কর জাগরণ যুগ (-10000 বছর থেকে -1000 বছর) <a class="header-anchor" href="#৪-অ্যাঙ্কর-জাগরণ-যুগ-10000-বছর-থেকে-1000-বছর" aria-label="Permalink to &quot;৪. অ্যাঙ্কর জাগরণ যুগ (-10000 বছর থেকে -1000 বছর)&quot;">​</a></h2><p>অ্যাঙ্কর জাগরণ যুগ হলো অ্যাঙ্কর প্রক্রিয়ার আবিষ্কার থেকে প্রাথমিক প্রয়োগ পর্যন্ত অতিবাহিত সময়। এই যুগের মূল বৈশিষ্ট্য হলো অ্যাঙ্কর প্রযুক্তির ধীরে ধীরে পরিপক্কতা এবং সিম্বায়োসিস চিন্তার বিস্তার।</p><table tabindex="0"><thead><tr><th>সময় নোড</th><th>গুরুত্বপূর্ণ ঘটনা</th></tr></thead><tbody><tr><td>-10000 বছর</td><td>অ্যাঙ্কর প্রক্রিয়া প্রথমবার আবিষ্কৃত হয়, আবিষ্কারক এটির নাম দেন &quot;অ্যাঙ্কর&quot;, এবং পদ্ধতিগত গবেষণা শুরু করেন</td></tr><tr><td>-9000 বছর</td><td>প্রথম কৃত্রিম অ্যাঙ্কর সফলভাবে প্রতিষ্ঠিত হয়, প্রমাণিত হয় যে অ্যাঙ্কর মানুষের দ্বারা নির্মাণ এবং রক্ষণাবেক্ষণ করা যায়</td></tr><tr><td>-8000 বছর</td><td>অ্যাঙ্কর প্রযুক্তি ছোট পরিসরে বিস্তারিত হতে শুরু করে, প্রথম ব্যাচের অ্যাঙ্কর ক্ষতিকর আবির্ভূত হয়</td></tr><tr><td>-7000 বছর</td><td>আবিষ্কৃত হয় যে অ্যাঙ্কর আন্তঃসমতল সংযোগের ভিত্তি হিসেবে ব্যবহার করা যায়, প্রথম রেকর্ডকৃত অ্যাঙ্কর-সহায়ক সমতল ভ্রমণ সফল হয়</td></tr><tr><td>-6000 বছর</td><td>সিম্বায়োসিস চিন্তা এবং অ্যাঙ্কর প্রযুক্তি একত্রিত হতে শুরু করে, প্রথম ব্যাচের &quot;অ্যাঙ্কর সিম্বায়োসিস&quot; তাত্ত্বিক নথি প্রকাশিত হয়</td></tr><tr><td>-5000 বছর</td><td>প্রথম অ্যাঙ্কর-ভিত্তিক সিম্বায়োসিস শৈলীর নগর রাষ্ট্র প্রতিষ্ঠিত হয়, সিম্বায়োসিস ব্যবস্থার সম্ভাব্যতা প্রমাণিত হয়</td></tr><tr><td>-4000 বছর</td><td>লুণ্ঠনশৈলী সভ্যতা সিম্বায়োসিস শৈলীর নগর রাষ্ট্রের উপর আক্রমণ চালায়, সিম্বায়োসিস নগর রাষ্ট্র অ্যাঙ্কর প্রযুক্তির মাধ্যমে সফলভাবে প্রতিরক্ষা করে</td></tr><tr><td>-3000 বছর</td><td>সিম্বায়োসিস চিন্তা একাধিক নক্ষত্র অঞ্চলে বিস্তারিত হয়, ক্রমশ বেশি সভ্যতা সিম্বায়োসিস রূপান্তর চেষ্টা করতে শুরু করে</td></tr><tr><td>-2000 বছর</td><td>প্রথম &quot;সব জাতির সিম্বায়োসিস সম্মেলন&quot; আয়োজিত হয়, কয়েক ডজন জাতির প্রতিনিধি একসাথে সিম্বায়োসিস সভ্যতার ভবিষ্যত নিয়ে আলোচনা করেন</td></tr><tr><td>-1000 বছর</td><td>অ্যাঙ্কর প্রযুক্তি এবং সিম্বায়োসিস চিন্তা ইতিমধ্যে একীভূত সভ্যতা প্রতিষ্ঠার শর্ত পূরণ করেছে, সিম্বায়োসিস ব্যবস্থা প্রতিষ্ঠার সময়কাল শুরু হয়</td></tr></tbody></table><h2 id="৫-সিম্বায়োসিস-ব্যবস্থা-প্রতিষ্ঠার-সময়কাল-1000-বছর-থেকে-100-বছর" tabindex="-1">৫. সিম্বায়োসিস ব্যবস্থা প্রতিষ্ঠার সময়কাল (-1000 বছর থেকে -100 বছর) <a class="header-anchor" href="#৫-সিম্বায়োসিস-ব্যবস্থা-প্রতিষ্ঠার-সময়কাল-1000-বছর-থেকে-100-বছর" aria-label="Permalink to &quot;৫. সিম্বায়োসিস ব্যবস্থা প্রতিষ্ঠার সময়কাল (-1000 বছর থেকে -100 বছর)&quot;">​</a></h2><p>সিম্বায়োসিস ব্যবস্থা প্রতিষ্ঠার সময়কাল হলো অ্যাঙ্কর সিম্বায়োসিস সভ্যতার প্রাতিষ্ঠানিক কাঠামোর শূন্য থেকে অস্তিত্বের গুরুত্বপূর্ণ সময়।</p><table tabindex="0"><thead><tr><th>সময় নোড</th><th>গুরুত্বপূর্ণ ঘটনা</th></tr></thead><tbody><tr><td>-1000 বছর</td><td>সিম্বায়োসিস সংবিধান খসড়া কমিটি গঠিত হয়, মৌলিক আইন খসড়া প্রস্তুত শুরু হয়</td></tr><tr><td>-950 বছর</td><td>&quot;সিম্বায়োসিস সংবিধান&quot; খসড়া সম্পন্ন হয়, ব্যাপকভাবে সব জাতির মতামত চাওয়া শুরু হয়</td></tr><tr><td>-900 বছর</td><td>&quot;সিম্বায়োসিস সংবিধান&quot; জাতীয় গণভোটের মাধ্যমে পাস হয়, আনুষ্ঠানিকভাবে কার্যকর হয়, অ্যাঙ্কর সিম্বায়োসিস সভ্যতা প্রতিষ্ঠার ঘোষণা করা হয়</td></tr><tr><td>-850 বছর</td><td>অ্যাঙ্কর কাউন্সিল, সিম্বায়োসিস কার্যকরী কমিটি, সিম্বায়োসিস আদালত তিনটি প্রধান সংস্থা আনুষ্ঠানিকভাবে গঠিত এবং কার্যকর হয়</td></tr><tr><td>-800 বছর</td><td>যৌথ উৎপাদন চুক্তি প্রক্রিয়া সমগ্র দেশে প্রবর্তন শুরু হয়</td></tr><tr><td>-700 বছর</td><td>&quot;সিম্বায়োসিস শ্রম আইন&quot;, &quot;ভোক্তা সুরক্ষা আইন&quot; ইত্যাদি মৌলিক আইন ধারাবাহিকভাবে প্রখ্যাপিত হয়</td></tr><tr><td>-600 বছর</td><td>শিক্ষা, চিকিৎসা, আবাসন, পরিবেশ, একচেটিয়াবিরোধী পাঁচটি সহায়ক আইন সম্পূর্ণরূপে প্রখ্যাপিত এবং কার্যকর হয়</td></tr><tr><td>-500 বছর</td><td>তিনশত সেট মূল ক্ষতি ব্যবস্থার উদ্ধার এবং সংগ্রহের কাজ আনুষ্ঠানিকভাবে শুরু হয়</td></tr><tr><td>-400 বছর</td><td>প্রথম পঞ্চাশটি মূল ক্ষতি ব্যবস্থা সংগ্রহ এবং যাচাই সম্পন্ন হয়</td></tr><tr><td>-300 বছর</td><td>দ্বিগুণ ফলের প্রযুক্তিগত প্রয়োগে অগ্রগতি লাভ হয়, শতগুণ অনুমান বৃদ্ধি প্রযুক্তি পরিপক্ক হয়</td></tr><tr><td>-200 বছর</td><td>তিনশত সেট ব্যবস্থা সম্পূর্ণরূপে সংগ্রহ সম্পন্ন হয়, চূড়ান্ত নিরাপত্তা যাচাই পর্যায়ে প্রবেশ করে</td></tr><tr><td>-100 বছর</td><td>তিনশত সেট মূল ক্ষতি ব্যবস্থা সম্পূর্ণরূপে খোলার শর্ত পরিপক্ক হয়, খোলার সময়কালে প্রবেশ করে</td></tr></tbody></table><h2 id="৬-তিনশত-সেট-ব্যবস্থা-খোলার-সময়কাল-100-বছর-থেকে-50-বছর" tabindex="-1">৬. তিনশত সেট ব্যবস্থা খোলার সময়কাল (-100 বছর থেকে -50 বছর) <a class="header-anchor" href="#৬-তিনশত-সেট-ব্যবস্থা-খোলার-সময়কাল-100-বছর-থেকে-50-বছর" aria-label="Permalink to &quot;৬. তিনশত সেট ব্যবস্থা খোলার সময়কাল (-100 বছর থেকে -50 বছর)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>সময় নোড</th><th>গুরুত্বপূর্ণ ঘটনা</th></tr></thead><tbody><tr><td>-100 বছর</td><td>তিনশত সেট মূল ক্ষতি ব্যবস্থা আনুষ্ঠানিকভাবে সমগ্র মহাবিশ্বের সত্ত্বাদের জন্য বিনামূল্যে খোলা হয়</td></tr><tr><td>-90 বছর</td><td>ক্ষতিকরদের সংখ্যা দশ বছরে শতগুণ বৃদ্ধি পায়, &quot;প্রত্যেকের পথ আছে&quot; প্রাথমিকভাবে বাস্তবায়িত হয়</td></tr><tr><td>-80 বছর</td><td>মূল তিনটি ভিত্তি (অনুমান পুনরাবৃত্তি, জীবন চক্র, স্থান নিয়ম নিয়ন্ত্রণ) সবচেয়ে জনপ্রিয় ব্যবস্থা হয়ে ওঠে</td></tr><tr><td>-70 বছর</td><td>নতুন ব্যবস্থার মাধ্যমে ক্ষতি করে উচ্চ স্তরে পৌঁছানো প্রথম ব্যাচের ক্ষতিকর আবির্ভূত হয়, ব্যবস্থার কার্যকারিতা প্রমাণিত হয়</td></tr><tr><td>-60 বছর</td><td>গুরু নেটওয়ার্ক সম্পূর্ণরূপে প্রতিষ্ঠিত হয়, উচ্চ-স্তরের ক্ষতিকররা প্রাথমিক ক্ষতিকরদের নির্দেশনা দেওয়ার আইনি বাধ্যতা পালন করতে শুরু করে</td></tr><tr><td>-50 বছর</td><td>সার্বজনীন ক্ষতি স্তর যথেষ্ট বৃদ্ধি পায়, 20% সক্রিয়করণ কৌশলের শর্ত পরিপক্ক হয়</td></tr></tbody></table><h2 id="৭-20-সক্রিয়করণ-কৌশলের-সময়কাল-50-বছর-থেকে-মূল-বছর" tabindex="-1">৭. 20% সক্রিয়করণ কৌশলের সময়কাল (-50 বছর থেকে মূল বছর) <a class="header-anchor" href="#৭-20-সক্রিয়করণ-কৌশলের-সময়কাল-50-বছর-থেকে-মূল-বছর" aria-label="Permalink to &quot;৭. 20% সক্রিয়করণ কৌশলের সময়কাল (-50 বছর থেকে মূল বছর)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>সময় নোড</th><th>গুরুত্বপূর্ণ ঘটনা</th></tr></thead><tbody><tr><td>-50 বছর</td><td>20% সক্রিয়করণ কৌশল আনুষ্ঠানিকভাবে শুরু হয়, লক্ষ্য হলো 50 বছরের মধ্যে 20% সত্ত্বাকে সক্রিয় করে সমতলের সর্বোচ্চ শক্তিশালী করা</td></tr><tr><td>-40 বছর</td><td>প্রথম ব্যাচের সমতলের সর্বোচ্চ শক্তিশালী জন্ম নেয়, সক্রিয়করণের হার 5% এ পৌঁছায়</td></tr><tr><td>-30 বছর</td><td>সক্রিয়করণের হার 10% এ পৌঁছায়, সমতলের সর্বোচ্চ শক্তিশালীরা অ্যাঙ্কর রক্ষণাবেক্ষণে মূল ভূমিকা পালন করতে শুরু করে</td></tr><tr><td>-20 বছর</td><td>সক্রিয়করণের হার 15% এ পৌঁছায়, মহাবিশ্বের সামগ্রিক ক্ষতি স্তর গুণগত বৃদ্ধি অর্জন করে</td></tr><tr><td>-10 বছর</td><td>সক্রিয়করণের হার 18% এ পৌঁছায়, কৌশলগত লক্ষ্যের কাছাকাছি</td></tr><tr><td>মূল বছর</td><td>সক্রিয়করণের হার 20.3% এ পৌঁছায়, 20% সক্রিয়করণ কৌশল সফলভাবে সম্পন্ন হয়, অ্যাঙ্কর সিম্বায়োসিস সভ্যতা নতুন যুগে প্রবেশ করে</td></tr></tbody></table><h2 id="৮-প্রথম-মাত্রা-বৃদ্ধি-যুগ-মূল-বছর-থেকে-100-বছর" tabindex="-1">৮. প্রথম মাত্রা বৃদ্ধি যুগ (মূল বছর থেকে 100 বছর) <a class="header-anchor" href="#৮-প্রথম-মাত্রা-বৃদ্ধি-যুগ-মূল-বছর-থেকে-100-বছর" aria-label="Permalink to &quot;৮. প্রথম মাত্রা বৃদ্ধি যুগ (মূল বছর থেকে 100 বছর)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>সময় নোড</th><th>গুরুত্বপূর্ণ ঘটনা</th></tr></thead><tbody><tr><td>মূল বছর</td><td>সিম্বায়োসিস সভ্যতা আনুষ্ঠানিকভাবে মাত্রা বৃদ্ধি যুগে প্রবেশের ঘোষণা করে, চার-পর্যায়ের মাত্রা বৃদ্ধি পথের প্রথম পর্যায় (বাস্তব ভিত্তি নির্মাণ) সম্পন্ন হয়</td></tr><tr><td>20 বছর</td><td>দ্বিতীয় পর্যায় (প্রযুক্তি ক্ষমতায়ন) সম্পূর্ণরূপে এগিয়ে যায়, ক্ষতি নিয়ম এবং প্রযুক্তি প্রকৌশল গভীরভাবে একীভূত হয়</td></tr><tr><td>40 বছর</td><td>কপি আয়না প্রযুক্তি, বিচ্ছিন্ন স্থান প্রযুক্তি প্রকৌশলগত উৎপাদন অর্জন করে, আন্তঃসমতল প্রত্নতত্ত্ব মাপকাঠির যুগে প্রবেশ করে</td></tr><tr><td>60 বছর</td><td>প্রথম ব্যাচের চেতনা মাত্রা বৃদ্ধি শ্রেণীর ক্ষতিকর উচ্চ স্তরে পৌঁছায়, তৃতীয় পর্যায় (চেতনা বিবর্তন) শুরু হয়</td></tr><tr><td>80 বছর</td><td>চেতনা ডোমেইনের মৌলিক অবকাঠামো নির্মাণ সম্পন্ন হয়, চেতনা স্থানান্তর প্রযুক্তি প্রাথমিকভাবে পরিপক্ক হয়</td></tr><tr><td>100 বছর</td><td>প্রথমবারের মতো পর্যায়ক্রমিক মাত্রা বৃদ্ধি সফল হয়, সিম্বায়োসিস সভ্যতা সামগ্রিকভাবে অর্ধেক মাত্রা স্তর বৃদ্ধি পায়</td></tr></tbody></table><h2 id="৯-সব-জাতির-প্রজাতন্ত্র-যুগ-100-বছর-থেকে-500-বছর" tabindex="-1">৯. সব জাতির প্রজাতন্ত্র যুগ (100 বছর থেকে 500 বছর) <a class="header-anchor" href="#৯-সব-জাতির-প্রজাতন্ত্র-যুগ-100-বছর-থেকে-500-বছর" aria-label="Permalink to &quot;৯. সব জাতির প্রজাতন্ত্র যুগ (100 বছর থেকে 500 বছর)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>সময় নোড</th><th>গুরুত্বপূর্ণ ঘটনা</th></tr></thead><tbody><tr><td>100 বছর</td><td>সব জাতির প্রজাতন্ত্র আনুষ্ঠানিকভাবে প্রতিষ্ঠার ঘোষণা করা হয়, সব বুদ্ধিমান জাতি সিম্বায়োসিস সভ্যতার কাঠামোর মধ্যে সমান মিলন অর্জন করে</td></tr><tr><td>150 বছর</td><td>সব জাতির নামতালিকা সম্পাদনা সম্পন্ন হয়, সব পরিচিত বুদ্ধিমান জাতি অন্তর্ভুক্ত করা হয়</td></tr><tr><td>200 বছর</td><td>আন্তঃজাতি বিবাহ এবং সাংস্কৃতিক সংমিশ্রণ স্বাভাবিক হয়ে ওঠে, নতুন মিশ্রিত জাতি আবির্ভূত হতে শুরু করে</td></tr><tr><td>300 বছর</td><td>সব জাতির সাধারণ ভাষার প্রচার সম্পন্ন হয়, আন্তঃজাতি যোগাযোগের বাধা মূলত নির্মূল হয়</td></tr><tr><td>400 বছর</td><td>সব জাতির সাংস্কৃতিক মহা বিকাশ, প্রতিটি জাতির ঐতিহ্যবাহী সংস্কৃতি সিম্বায়োসিস কাঠামোর মধ্যে সুরক্ষিত এবং বিকশিত হয়</td></tr><tr><td>500 বছর</td><td>সব জাতির প্রজাতন্ত্র পরিপক্কতার পর্যায়ে প্রবেশ করে, আন্তঃসমতল অনুসন্ধানের শর্ত সম্পূর্ণরূপে পরিপক্ক হয়</td></tr></tbody></table><h2 id="১০-আন্তঃসমতল-অনুসন্ধান-যুগ-500-বছর-থেকে-2000-বছর" tabindex="-1">১০. আন্তঃসমতল অনুসন্ধান যুগ (500 বছর থেকে 2000 বছর) <a class="header-anchor" href="#১০-আন্তঃসমতল-অনুসন্ধান-যুগ-500-বছর-থেকে-2000-বছর" aria-label="Permalink to &quot;১০. আন্তঃসমতল অনুসন্ধান যুগ (500 বছর থেকে 2000 বছর)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>সময় নোড</th><th>গুরুত্বপূর্ণ ঘটনা</th></tr></thead><tbody><tr><td>500 বছর</td><td>বৃহৎ আকারের আন্তঃসমতল অনুসন্ধান পরিকল্পনা আনুষ্ঠানিকভাবে শুরু হয়, সমতল ব্যবস্থাপনা অধিদপ্তর গঠিত হয়</td></tr><tr><td>600 বছর</td><td>অনুসন্ধান করা সমতলের সংখ্যা হাজার ছাড়িয়ে যায়, সমতল স্থানাঙ্ক মূল ভাণ্ডার প্রাথমিকভাবে নির্মিত হয়</td></tr><tr><td>800 বছর</td><td>কপি আয়না বিদেশী প্রত্নতত্ত্ব পরিকল্পনা সম্পূর্ণরূপে পরিপক্ক হয়, আন্তঃসমতল প্রত্নতত্ত্ব সোনালী যুগে প্রবেশ করে</td></tr><tr><td>1000 বছর</td><td>সময় প্রত্যাবর্তন প্রযুক্তিতে অগ্রগতি লাভ হয়, প্রথমে পর্যবেক্ষণ তারপর সীমিত হস্তক্ষেপের নীতি আনুষ্ঠানিকভাবে প্রতিষ্ঠিত হয়</td></tr><tr><td>1200 বছর</td><td>অনুসন্ধান করা সমতলের সংখ্যা এক লক্ষ ছাড়িয়ে যায়, কয়েক ডজন সমতল সভ্যতার সাথে কূটনৈতিক সম্পর্ক স্থাপন করা হয়</td></tr><tr><td>1500 বছর</td><td>আন্তঃসমতল নৈতিক নীতি সম্পূর্ণরূপে কার্যকর হয়, সভ্যতার মধ্যে মিথস্ক্রিয়া মানকীকৃত যুগে প্রবেশ করে</td></tr><tr><td>1800 বছর</td><td>সময় প্যারাডক্স প্রতিরোধ ব্যবস্থা সম্পূর্ণরূপে পরিপক্ক হয়, সময় প্রত্যাবর্তন প্রত্নতত্ত্ব মাপকাঠির আকার অর্জন করে</td></tr><tr><td>2000 বছর</td><td>আন্তঃসমতল অনুসন্ধানে চমকপ্রদ ফলাফল অর্জিত হয়, আন্তঃনাক্ষত্রিক সিম্বায়োসিস যুগের শর্ত সম্পূর্ণরূপে পরিপক্ক হয়</td></tr></tbody></table><h2 id="১১-আন্তঃনাক্ষত্রিক-সিম্বায়োসিস-যুগ-2000-বছর-থেকে-ভবিষ্যত" tabindex="-1">১১. আন্তঃনাক্ষত্রিক সিম্বায়োসিস যুগ (2000 বছর থেকে ভবিষ্যত) <a class="header-anchor" href="#১১-আন্তঃনাক্ষত্রিক-সিম্বায়োসিস-যুগ-2000-বছর-থেকে-ভবিষ্যত" aria-label="Permalink to &quot;১১. আন্তঃনাক্ষত্রিক সিম্বায়োসিস যুগ (2000 বছর থেকে ভবিষ্যত)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>সময় নোড</th><th>গুরুত্বপূর্ণ ঘটনা</th></tr></thead><tbody><tr><td>2000 বছর</td><td>আন্তঃনাক্ষত্রিক সিম্বায়োসিস যুগ আনুষ্ঠানিকভাবে শুরু হয়, চতুর্থ পর্যায় (আন্তঃনাক্ষত্রিক সিম্বায়োসিস) সম্পূর্ণরূপে এগিয়ে যায়</td></tr><tr><td>2500 বছর (প্রত্যাশা)</td><td>মহাজাগতিক অ্যাঙ্কর নেটওয়ার্ক প্রাথমিকভাবে নির্মিত হয়, অনুসন্ধান করা সমস্ত সমতলকে কভার করে</td></tr><tr><td>3000 বছর (প্রত্যাশা)</td><td>আন্তঃসমতল সিম্বায়োসিস ব্যবস্থা পরিপক্ক হয়, সব জাতি মহাবিশ্বের পরিসরে প্রকৃত সিম্বায়োসিস অর্জন করে</td></tr><tr><td>5000 বছর (প্রত্যাশা)</td><td>মহাবিশ্বের সামগ্রিক মাত্রা বৃদ্ধি সম্পন্ন হয়, হেঙ্গুয়ানঝো উচ্চতর মাত্রার অস্তিত্বের অবস্থায় প্রবেশ করে</td></tr><tr><td>ভবিষ্যত (প্রত্যাশা)</td><td>অ্যাঙ্কর সিম্বায়োসিস সভ্যতা মহাবিশ্বের বাইরে অনুসন্ধান চালিয়ে যায়, সিম্বায়োসিস ধারণাকে আরও বিস্তৃত অস্তিত্বে ছড়িয়ে দেয়</td></tr></tbody></table><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>ক্রনিকলের সংক্ষিপ্ত সারণিটি হলো অ্যাঙ্কর সিম্বায়োসিস সভ্যতার অজ্ঞানতা থেকে জাগরণ, দুর্বলতা থেকে শক্তিশালীতা, নিজস্ব সমতল থেকে সমগ্র মহাবিশ্ব পর্যন্ত সংগ্রামের মহাকাব্য। প্রতিটি যুগের পরিবর্তন হলো সিম্বায়োসিস ধারণার লুণ্ঠন ধারণার উপর বিজয়, সভ্যতার অগ্রগতির বর্বর পতনের উপর বিজয়ের সাক্ষ্য। ইতিহাস হলো অতীতের ধুলো নয়, বরং ভবিষ্যতের বীজ—এই ইতিহাসটি বোঝা মানে বোঝা সিম্বায়োসিস সভ্যতা কোথা থেকে এসেছে এবং কোথায় যাচ্ছে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>70-যুগ বিভাজনের সারসংক্ষেপ সারণি</li><li>72-অ্যাঙ্কর জাগরণ যুগ</li><li>79-আন্তঃনাক্ষত্রিক সিম্বায়োসিস যুগের প্রত্যাশা</li></ul>',32)])])}const c=d(h,[["render",o]]);export{s as __pageData,c as default};
